class Solution {
  public int countEffective(int[] nums) {
    final long MOD = 1_000_000_007L;
    int n = nums.length, BITS = 20, size = 1 << BITS;
    int total = 0;
    int[] f = new int[size];
    for (int x : nums) {
      total |= x;
      f[x]++;
    }
    for (int b = 0; b < BITS; b++)
      for (int mask = 0; mask < size; mask++)
        if ((mask >> b & 1) != 0) f[mask] += f[mask ^ (1 << b)];
    long[] pow2 = new long[n + 1];
    pow2[0] = 1;
    for (int i = 1; i <= n; i++) pow2[i] = pow2[i - 1] * 2 % MOD;
    long ans = 0;
    for (int sub = total; sub > 0; sub = (sub - 1) & total) {
      int comp = (size - 1) ^ sub;
      long term = pow2[f[comp]];
      if (Integer.bitCount(sub) % 2 == 1) ans += term;
      else ans -= term;
    }
    return (int) (((ans % MOD) + MOD) % MOD);
  }
}
